def calculate_checksum(buffer):
    """Calcula la suma de comprobación como la suma de todos los bytes en el búfer."""
    return sum(buffer)

def main():
    input_filename = "input.dat"  # Nombre del archivo de entrada
    output_filename = "output.dat"  # Nombre del archivo de salida

    try:
        # Leer el contenido del archivo en un búfer (como bytes)
        with open(input_filename, "rb") as file:
            buffer = file.read()

        # Calcular la suma de comprobación
        checksum = calculate_checksum(buffer)

        # Verificar si el búfer está vacío (checksum == 0)
        if checksum == 0:
            print("El búfer está vacío.")
        else:
            print(f"Bytes leídos: {len(buffer)}, Suma de comprobación: {checksum}")

        # Guardar la cantidad de bytes leídos y la suma de verificación en otro archivo
        with open(output_filename, "w") as output_file:
            output_file.write(f"Bytes leídos: {len(buffer)}\n")
            output_file.write(f"Suma de comprobación: {checksum}\n")

        print(f"Datos guardados en {output_filename}")

    except FileNotFoundError:
        print(f"Error: El archivo {input_filename} no fue encontrado.")
    except PermissionError:
        print(f"Error: No se tiene permiso para leer el archivo {input_filename} o escribir en {output_filename}.")
    except Exception as e:
        print(f"Ocurrió un error inesperado: {e}")

if __name__ == "__main__":
    main()
